# Created by OpenAI
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

_SHARED = gl.SwizzledSharedLayout(16, 1, 8, [1, 0])

@gluon.jit
def _read_shared(tile, LAYOUT: gl.constexpr, ASYNC: gl.constexpr):
    if ASYNC:
        return gl.amd.cdna4.async_copy.load_shared_relaxed(tile, LAYOUT)
    else:
        return tile.load(LAYOUT)

@gluon.jit
def _stage_query(q, qr, ROPE: gl.constexpr, TYPE: gl.constexpr):
    return (gl.allocate_shared_memory(TYPE, [16, 512], _SHARED, q.to(TYPE)), gl.allocate_shared_memory(TYPE, [16, ROPE], _SHARED, qr.to(TYPE)))

@gluon.jit
def _store_output(Out, result, head_row, x, panel, CHANNELS: gl.constexpr):
    result = result.to(gl.bfloat16)
    if CHANNELS < 128:
        d = x & 3 | (x & 4) << 4 | (x & 120) >> 1 | x & 384
    else:
        result = result.reshape((CHANNELS // 128, 4, 4, 2, 4)).permute((0, 3, 1, 2, 4)).reshape((CHANNELS,))
        layout: gl.constexpr = gl.BlockedLayout([4], [64], [1], [0])
        result = gl.convert_layout(result, layout)
        d = panel * CHANNELS + gl.arange(0, CHANNELS, layout)
    gl.store(Out + head_row * 512 + d, result)

@gluon.jit
def _exp_mode(x, FAST: gl.constexpr):
    if FAST:
        return gl.exp2(x * 1.4426950408889634)
    else:
        return gl.exp(x)

@gluon.jit
def _qk_operands(q, k, acc, NATIVE: gl.constexpr):
    if NATIVE:
        return gl.amd.cdna4.mfma_scaled(q, None, 'e4m3', k, None, 'e4m3', acc)
    else:
        return gl.amd.cdna4.mfma(q, k.to(gl.bfloat16), acc)
